using Microsoft.ML;
using Microsoft.Extensions.ObjectPool;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketModelService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<TicketModelService> _logger;
    private readonly Lock _lock = new();
    private ObjectPool<PredictionEngine<TicketData, TicketPrediction>>? _predictionPool;

    public TicketModelService(ILogger<TicketModelService> logger, IWebHostEnvironment env)
    {
        _logger = logger;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
    }

    public EvaluationResult TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        var pipeline = _mlContext.Transforms.Text
                .FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(split.TrainSet);
        _mlContext.Model.Save(model, split.TrainSet.Schema, _modelPath);

        // Build a thread-safe prediction pool from the trained model
        lock (_lock)
        {
            var policy = new PredictionEnginePoolPolicy(_mlContext, model);
            _predictionPool = new DefaultObjectPool<PredictionEngine<TicketData, TicketPrediction>>(policy);
        }

        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation(
            "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        return new EvaluationResult
        {
            MicroAccuracy = metrics.MicroAccuracy,
            MacroAccuracy = metrics.MacroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction,
        };
    }

    public TicketPrediction? Predict(TicketData input)
    {
        ObjectPool<PredictionEngine<TicketData, TicketPrediction>>? pool;
        lock (_lock) { pool = _predictionPool; }
        if (pool is null) return null;

        var engine = pool.Get();
        try
        {
            return engine.Predict(input);
        }
        finally
        {
            pool.Return(engine);
        }
    }

    public bool ModelReady
    {
        get { lock (_lock) { return _predictionPool is not null; } }
    }

    private sealed class PredictionEnginePoolPolicy(
        MLContext mlContext,
        ITransformer model) : PooledObjectPolicy<PredictionEngine<TicketData, TicketPrediction>>
    {
        public override PredictionEngine<TicketData, TicketPrediction> Create()
            => mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(model);

        public override bool Return(PredictionEngine<TicketData, TicketPrediction> obj) => true;
    }
}

